\n    \"node_modules/yn\": {\r\n      \"version\": \"3.1.1\",\r\n      \"resolved\": \"https://registry.npmjs.org/yn/-/yn-3.1.1.tgz\",\r\n      \"integrity\": \"sha512-Ux4ygGWsu2c7isFWe8Yu1YluJmqVhxqK2cLXNQA5AcC3QfbGNpM7fu0Y8b/z16pXLnFxZYvWhd3fhBY9DLmC6Q==\",\r\n      \"dev\": true,\r\n      \"license\": \"MIT\",\r\n      \"engines\": {\r\n        \"node\": \"\u003e=6\"\r\n      }\r\n    }\r\n  }\r\n}\r\n\n```\n\n### package.json\n```\n{\r\n  \"name\": \"azure-key-vault-config-provider\",\r\n  \"version\": \"1.0.0\",\r\n  \"private\": true,\r\n  \"description\": \"TypeScript Node.js configuration provider backed by Azure Key Vault.\",\r\n  \"main\": \"dist/index.js\",\r\n  \"types\": \"dist/index.d.ts\",\r\n  \"scripts\": {\r\n    \"build\": \"tsc -p tsconfig.json\",\r\n    \"demo\": \"ts-node src/index.ts\",\r\n    \"start\": \"node dist/index.js\"\r\n  },\r\n  \"dependencies\": {\r\n    \"@azure/identity\": \"^4.10.1\",\r\n    \"@azure/keyvault-secrets\": \"^4.10.0\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"@types/node\": \"^22.15.17\",\r\n    \"ts-node\": \"^10.9.2\",\r\n    \"typescript\": \"^5.8.3\"\r\n  }\r\n}\r\n\n```\n\n### src\\config.ts\n```\nimport { ManagedIdentityCredential } from \"@azure/identity\";\r\nimport { SecretClient } from \"@azure/keyvault-secrets\";\r\nimport { KeyVaultSecretProvider } from \"./keyVaultSecretProvider\";\r\nimport { SecretCache } from \"./secretCache\";\r\nimport { SecretRotationHelper } from \"./secretRotationHelper\";\r\n\r\nexport const KEY_VAULT_URL_ENV = \"KEY_VAULT_URL\";\r\n\r\nexport interface ConfigurationModule {\r\n  vaultUrl: string;\r\n  credential: ManagedIdentityCredential;\r\n  secretClient: SecretClient;\r\n  secretProvider: KeyVaultSecretProvider;\r\n  secretCache: SecretCache;\r\n  secretRotationHelper: SecretRotationHelper;\r\n}\r\n\r\nexport function createConfigurationModule(): ConfigurationModule {\r\n  const vaultUrl = process.env[KEY_VAULT_URL_ENV];\r\n\r\n  if (!vaultUrl) {\r\n    throw new Error(\r\n      `Missing ${KEY_VAULT_URL_ENV}. Set it to your Azure Key Vault URL.`,\r\n    );\r\n  }\r\n\r\n  const credential = new ManagedIdentityCredential();\r\n  const secretClient = new SecretClient(vaultUrl, credential);\r\n  const secretProvider = new KeyVaultSecretProvider(secretClient);\r\n  const secretCache = new SecretCache(secretProvider);\r\n  const secretRotationHelper = new SecretRotationHelper(secretClient);\r\n\r\n  return {\r\n    vaultUrl,\r\n    credential,\r\n    secretClient,\r\n    secretProvider,\r\n    secretCache,\r\n    secretRotationHelper,\r\n  };\r\n}\r\n\n```\n\n### src\\index.ts\n```\nimport { createConfigurationModule } from \"./config\";\r\nimport { ResolvedSecret } from \"./keyVaultSecretProvider\";\r\nimport { CachedSecret, RequiredSecretDefinition } from \"./secretCache\";\r\n\r\nfunction addDays(days: number): Date {\r\n  return new Date(Date.now() + days * 24 * 60 * 60 * 1000);\r\n}\r\n\r\nfunction printSecret(\r\n  label: string,\r\n  secret: CachedSecret | ResolvedSecret,\r\n): void {\r\n  console.log(label, secret);\r\n}\r\n\r\nfunction requireVersion(version: string | undefined, secretName: string): string {\r\n  if (!version) {\r\n    throw new Error(`Secret \"${secretName}\" did not return a version identifier.`);\r\n  }\r\n\r\n  return version;\r\n}\r\n\r\nasync function main(): Promise\u003cvoid\u003e {\r\n  const configuration = createConfigurationModule();\r\n  const { secretProvider, secretCache, secretRotationHelper } = configuration;\r\n\r\n  console.log(`Connected to vault: ${configuration.vaultUrl}`);\r\n\r\n  const requiredSecrets: RequiredSecretDefinition[] = [\r\n    {\r\n      name: \"App--ApiBaseUrl\",\r\n      defaultValue: \"https://fallback.example.internal\",\r\n    },\r\n    {\r\n      name: \"App--FeatureFlag\",\r\n      defaultValue: \"disabled\",\r\n    },\r\n    {\r\n      name: \"App--ConnectionString\",\r\n      defaultValue: \"UseDevelopmentStorage=true\",\r\n    },\r\n  ];\r\n\r\n  const preloaded = await secretCache.preload(requiredSecrets);\r\n  console.log(\"\\nLoaded required configuration keys at startup:\");\r\n  preloaded.forEach((secret) =\u003e printSecret(\"  -\u003e\", secret));\r\n\r\n  const cachedConnectionString = await secretCache.get(\"App--ConnectionString\", {\r\n    defaultValue: \"UseDevelopmentStorage=true\",\r\n  });\r\n  console.log(\"\\nRead one key from cache:\");\r\n  printSecret(\"  -\u003e\", cachedConnectionString);\r\n\r\n  const refreshedFeatureFlag = await secretCache.refresh(\"App--FeatureFlag\", {\r\n    defaultValue: \"disabled\",\r\n  });\r\n  console.log(\"\\nRefreshed one key on demand:\");\r\n  printSecret(\"  -\u003e\", refreshedFeatureFlag);\r\n\r\n  const demoSecretName =\r\n    process.env.DEMO_SECRET_NAME ?? `demo-config-${Date.now()}`;\r\n\r\n  const firstVersion = await secretRotationHelper.rotateSecret(\r\n    demoSecretName,\r\n    \"initial-demo-value\",\r\n    addDays(3),\r\n  );\r\n  const firstVersionId = requireVersion(\r\n    firstVersion.properties.version,\r\n    demoSecretName,\r\n  );\r\n  console.log(\"\\nCreated an initial demo secret version:\");\r\n  console.log(`  -\u003e name=${demoSecretName}, version=${firstVersionId}`);\r\n\r\n  await secretCache.refresh(demoSecretName);\r\n  await secretCache.refreshExpiringSecrets();\r\n\r\n  const nearExpiry = secretCache.getExpiringSecrets();\r\n  if (nearExpiry.length \u003e 0) {\r\n    console.log(\"\\nWarning: these secrets are near expiry:\");\r\n    nearExpiry.forEach((secret) =\u003e printSecret(\"  -\u003e\", secret));\r\n  } else {\r\n    console.log(\"\\nNo secrets are near expiry.\");\r\n  }\r\n\r\n  const rotatedSecret = await secretRotationHelper.rotateSecret(\r\n    demoSecretName,\r\n    \"rotated-demo-value\",\r\n    addDays(30),\r\n  );\r\n  const rotatedVersionId = requireVersion(\r\n    rotatedSecret.properties.version,\r\n    demoSecretName,\r\n  );\r\n  console.log(\"\\nCreated a new secret version during rotation:\");\r\n  console.log(`  -\u003e name=${demoSecretName}, version=${rotatedVersionId}`);\r\n\r\n  const originalVersion = await secretProvider.getSecretVersion(\r\n    demoSecretName,\r\n    firstVersionId,\r\n  );\r\n  console.log(\"\\nFetched the previous version explicitly:\");\r\n  printSecret(\"  -\u003e\", originalVersion);\r\n\r\n  const latestVersion = await secretCache.refresh(demoSecretName);\r\n  console.log(\"\\nRefreshed cache with the newest version:\");\r\n  printSecret(\"  -\u003e\", latestVersion);\r\n\r\n  await secretRotationHelper.deleteAndPurgeSecret(demoSecretName);\r\n  console.log(\r\n    \"\\nDeleted and purged the demo secret. The name is now fully reusable.\",\r\n  );\r\n}\r\n\r\nmain().catch((error: unknown) =\u003e {\r\n  console.error(\"Demo failed.\", error);\r\n  process.exitCode = 1;\r\n});\r\n\n```\n\n### src\\keyVaultSecretProvider.ts\n```\nimport { SecretClient } from \"@azure/keyvault-secrets\";\r\n\r\nexport interface SecretFetchOptions {\r\n  defaultValue?: string;\r\n  version?: string;\r\n}\r\n\r\nexport interface ResolvedSecret {\r\n  name: string;\r\n  value: string;\r\n  version?: string;\r\n  expiresOn?: Date;\r\n  usedDefault: boolean;\r\n}\r\n\r\nfunction isNotFoundError(error: unknown): boolean {\r\n  return (\r\n    typeof error === \"object\" \u0026\u0026\r\n    error !== null \u0026\u0026\r\n    \"statusCode\" in error \u0026\u0026\r\n    error.statusCode === 404\r\n  );\r\n}\r\n\r\nexport class KeyVaultSecretProvider {\r\n  public constructor(private readonly client: SecretClient) {}\r\n\r\n  public async getSecret(\r\n    name: string,\r\n    options: SecretFetchOptions = {},\r\n  ): Promise\u003cResolvedSecret\u003e {\r\n    try {\r\n      const secret = await this.client.getSecret(name, {\r\n        version: options.version,\r\n      });\r\n\r\n      if (secret.value === undefined) {\r\n        throw new Error(`Secret \"${name}\" does not contain a value.`);\r\n      }\r\n\r\n      return {\r\n        name: secret.name,\r\n        value: secret.value,\r\n        version: secret.properties.version,\r\n        expiresOn: secret.properties.expiresOn,\r\n        usedDefault: false,\r\n      };\r\n    } catch (error) {\r\n      if (isNotFoundError(error) \u0026\u0026 options.defaultValue !== undefined) {\r\n        return {\r\n          name,\r\n          value: options.defaultValue,\r\n          version: options.version,\r\n          usedDefault: true,\r\n        };\r\n      }\r\n\r\n      throw error;\r\n    }\r\n  }\r\n\r\n  public async getSecretVersion(\r\n    name: string,\r\n    version: string,\r\n    defaultValue?: string,\r\n  ): Promise\u003cResolvedSecret\u003e {\r\n    return this.getSecret(name, {\r\n      defaultValue,\r\n      version,\r\n    });\r\n  }\r\n\r\n  public async getSecretExpiry(\r\n    name: string,\r\n    version?: string,\r\n  ): Promise\u003cDate | undefined\u003e {\r\n    const secret = await this.getSecret(name, { version });\r\n    return secret.expiresOn;\r\n  }\r\n\r\n  public isExpiringSoon(\r\n    secret: Pick\u003cResolvedSecret, \"expiresOn\"\u003e,\r\n    warningWindowMs: number,\r\n  ): boolean {\r\n    if (!secret.expiresOn) {\r\n      return false;\r\n    }\r\n\r\n    return secret.expiresOn.getTime() - Date.now() \u003c= warningWindowMs;\r\n  }\r\n}\r\n\n```\n\n### src\\secretCache.ts\n```\nimport {\r\n  KeyVaultSecretProvider,\r\n  ResolvedSecret,\r\n  SecretFetchOptions,\r\n} from \"./keyVaultSecretProvider\";\r\n\r\nexport interface RequiredSecretDefinition extends SecretFetchOptions {\r\n  name: string;\r\n}\r\n\r\nexport interface CachedSecret extends ResolvedSecret {\r\n  cacheKey: string;\r\n  cachedAt: Date;\r\n  requestedVersion?: string;\r\n  defaultValue?: string;\r\n}\r\n\r\nexport interface SecretCacheOptions {\r\n  expiryWarningWindowMs?: number;\r\n}\r\n\r\nexport class SecretCache {\r\n  private readonly cache = new Map\u003cstring, CachedSecret\u003e();\r\n  private readonly expiryWarningWindowMs: number;\r\n\r\n  public constructor(\r\n    private readonly provider: KeyVaultSecretProvider,\r\n    options: SecretCacheOptions = {},\r\n  ) {\r\n    this.expiryWarningWindowMs =\r\n      options.expiryWarningWindowMs ?? 7 * 24 * 60 * 60 * 1000;\r\n  }\r\n\r\n  public async preload(\r\n    requiredSecrets: RequiredSecretDefinition[],\r\n  ): Promise\u003cCachedSecret[]\u003e {\r\n    return Promise.all(\r\n      requiredSecrets.map((secret) =\u003e\r\n        this.refresh(secret.name, {\r\n          defaultValue: secret.defaultValue,\r\n          version: secret.version,\r\n        }),\r\n      ),\r\n    );\r\n  }\r\n\r\n  public async get(\r\n    name: string,\r\n    options: SecretFetchOptions = {},\r\n  ): Promise\u003cCachedSecret\u003e {\r\n    const key = this.toCacheKey(name, options.version);\r\n    const existing = this.cache.get(key);\r\n\r\n    if (!existing) {\r\n      return this.refresh(name, options);\r\n    }\r\n\r\n    if (this.provider.isExpiringSoon(existing, this.expiryWarningWindowMs)) {\r\n      return this.refresh(name, {\r\n        defaultValue: existing.defaultValue,\r\n        version: existing.requestedVersion,\r\n      });\r\n    }\r\n\r\n    return existing;\r\n  }\r\n\r\n  public async refresh(\r\n    name: string,\r\n    options: SecretFetchOptions = {},\r\n  ): Promise\u003cCachedSecret\u003e {\r\n    const resolved = await this.provider.getSecret(name, options);\r\n    const cached: CachedSecret = {\r\n      ...resolved,\r\n      cacheKey: this.toCacheKey(name, options.version),\r\n      cachedAt: new Date(),\r\n      requestedVersion: options.version,\r\n      defaultValue: options.defaultValue,\r\n    };\r\n\r\n    this.cache.set(cached.cacheKey, cached);\r\n    return cached;\r\n  }\r\n\r\n  public async refreshExpiringSecrets(): Promise\u003cCachedSecret[]\u003e {\r\n    const expiringEntries = Array.from(this.cache.values()).filter((entry) =\u003e\r\n      this.provider.isExpiringSoon(entry, this.expiryWarningWindowMs),\r\n    );\r\n\r\n    return Promise.all(\r\n      expiringEntries.map((entry) =\u003e\r\n        this.refresh(entry.name, {\r\n          defaultValue: entry.defaultValue,\r\n          version: entry.requestedVersion,\r\n        }),\r\n      ),\r\n    );\r\n  }\r\n\r\n  public getExpiringSecrets(): CachedSecret[] {\r\n    return Array.from(this.cache.values()).filter((entry) =\u003e\r\n      this.provider.isExpiringSoon(entry, this.expiryWarningWindowMs),\r\n    );\r\n  }\r\n\r\n  public snapshot(): CachedSecret[] {\r\n    return Array.from(this.cache.values());\r\n  }\r\n\r\n  private toCacheKey(name: string, version?: string): string {\r\n    return version ? `${name}@${version}` : name;\r\n  }\r\n}\r\n\n```\n\n### src\\secretRotationHelper.ts\n```\nimport { SecretClient, KeyVaultSecret } from \"@azure/keyvault-secrets\";\r\n\r\nexport class SecretRotationHelper {\r\n  public constructor(private readonly client: SecretClient) {}\r\n\r\n  public async rotateSecret(\r\n    name: string,\r\n    value: string,\r\n    expiresOn: Date,\r\n  ): Promise\u003cKeyVaultSecret\u003e {\r\n    return this.client.setSecret(name, value, { expiresOn });\r\n  }\r\n\r\n  public async deleteAndPurgeSecret(name: string): Promise\u003cvoid\u003e {\r\n    const poller = await this.client.beginDeleteSecret(name);\r\n    await poller.pollUntilDone();\r\n    await this.client.purgeDeletedSecret(name);\r\n  }\r\n}\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2022\",\r\n    \"module\": \"CommonJS\",\r\n    \"moduleResolution\": \"node\",\r\n    \"rootDir\": \"src\",\r\n    \"outDir\": \"dist\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"skipLibCheck\": true,\r\n    \"declaration\": true\r\n  },\r\n  \"include\": [\r\n    \"src/**/*.ts\"\r\n  ]\r\n}\r\n\n```\n\n## Reference Answer\n\nNo reference answer provided.\n\n# Review Scoring Rubric\r\n\r\nYou are a senior Azure SDK code reviewer evaluating generated code.\r\n\r\